const quercia=(g,x,y,s,t)=>{ln(g,'#5a4028',7*s,[x,y,x+2*s,y-26*s,x-2*s,y-44*s]);ln(g,'#5a4028',4*s,[x,y-26*s,x+16*s,y-44*s]);const w=Math.sin((t||0)*.8+x)*1.2;[[-18,-62,26,17,'#3a6a34'],[16,-60,24,16,'#44763a'],[0,-78,24,15,'#3a6a34'],[-4,-54,22,12,'#2e5a2c']].forEach(p=>el(g,p[4],x+(p[0]+w)*s,y+p[1]*s,p[2]*s,p[3]*s))};
const capanna=(g,x,y,w,h,tt)=>{rect(g,'#b89868',x-w/2,y-h*.5,w,h*.5);for(let q=0;q<=Math.floor(w/8);q++)ln(g,'#8a6a40',1.6,[x-w/2+q*8,y,x-w/2+q*8,y-h*.5]);poly(g,'#d8c070',[[x-w/2-8,y-h*.45],[x,y-h-8],[x+w/2+8,y-h*.45]]);for(let q=0;q<7;q++)ln(g,'rgba(120,90,30,.4)',1.2,[x,y-h-8,x-w/2-6+q*(w+12)/6,y-h*.45]);rect(g,'#2a1c10',x-w*.12,y-h*.36,w*.24,h*.36);if(tt!=null)fumo(g,x+2,y-h-6,tt,4)};
