const insula=(g,x,y,w,h,i,k,c)=>{const cc=c||['#d8a878','#c88a5a','#e0c090'][md(i,3)];rect(g,cc,x-w/2,y-h,w,h);rect(g,'rgba(0,0,0,.14)',x+w*.22,y-h,w*.28,h);poly(g,['#a8503a','#8a3a2a'][md(i,2)],[[x-w/2-4,y-h],[x,y-h-24],[x+w/2+4,y-h]]);for(let r=0;r<Math.floor(h/34);r++)for(let q=0;q<2;q++)rect(g,lit(k,i*5+r*2+q)?LIT:'#3a2e24',x-w*.3+q*w*.4,y-h+10+r*34,w*.18,16);rect(g,'#2a1c10',x-w*.12,y-26,w*.24,26)};
